    const playerName=(playerId && nameOf(playerId)!=='未知联系人' ? nameOf(playerId) : '') || all.find(message=>message.sender===PHONE_PLAYER && message.name)?.name || '';
    const contactName=(shownThread || (shown ? threads.get(shown) : null))?.name || '未知联系人';
