    const faces=React.useSyncExternalStore(faceCache?.subscribe || cardFaceNoSubscribe,()=>faceCache ? names.map(name=>{const face=cardFace(name);return face && (px && faceCache.get(face,px) || faceCache.ready(face)) || '';}).join('\n') : '');
